export const CONTRACT_TITLE_KEY = 'contractTitle';
export const CONTRACT_BODY_KEY = 'contractBody';
export const CONTRACT_PARTY_A_KEY = 'contractPartyA';
export const CONTRACT_TEMPLATE_VERSION = '2';

export type ContractPartyA = {
  name: string;
  creditCode: string;
  address: string;
  legalRep: string;
  phone: string;
  email: string;
};

export const DEFAULT_PARTY_A: ContractPartyA = {
  name: '上海御炎川科技有限公司',
  creditCode: '9131310117MADUN8F788',
  address: '上海市松江区石湖荡镇长石路499号57幢',
  legalRep: '',
  phone: '',
  email: '',
};

export function fillContractTemplate(content: string, vars: Record<string, string>) {
  let text = String(content || '');
  Object.entries(vars).forEach(([key, value]) => {
    const token = key.startsWith('{{') ? key : '{{' + key + '}}';
    const safe = value == null || value === '' ? '_______________' : String(value);
    text = text.split(token).join(safe);
  });
  return text;
}

export function parsePartyA(raw?: string | null): ContractPartyA {
  try {
    const data = raw ? JSON.parse(raw) : {};
    return {
      name: String(data.name || DEFAULT_PARTY_A.name).trim() || DEFAULT_PARTY_A.name,
      creditCode: String(data.creditCode || DEFAULT_PARTY_A.creditCode).trim() || DEFAULT_PARTY_A.creditCode,
      address: String(data.address || DEFAULT_PARTY_A.address).trim() || DEFAULT_PARTY_A.address,
      legalRep: String(data.legalRep || '').trim(),
      phone: String(data.phone || '').trim(),
      email: String(data.email || '').trim(),
    };
  } catch {
    return { ...DEFAULT_PARTY_A };
  }
}

export function formatCnDate(date = new Date()) {
  return `${date.getFullYear()}年${date.getMonth() + 1}月${date.getDate()}日`;
}

export function buildContractNo(userId: number, semesterId?: number | null) {
  const d = new Date();
  const y = d.getFullYear();
  const m = `${d.getMonth() + 1}`.padStart(2, '0');
  const day = `${d.getDate()}`.padStart(2, '0');
  const sem = semesterId ? String(semesterId).padStart(3, '0') : '000';
  return `HTC-${y}${m}${day}-${sem}-${String(userId).padStart(4, '0')}`;
}

export type ContractFillInput = {
  partyA: ContractPartyA;
  realName?: string | null;
  idNumber?: string | null;
  address?: string | null;
  phone?: string | null;
  email?: string | null;
  bankName?: string | null;
  bankAccountName?: string | null;
  bankAccount?: string | null;
  semesterName?: string | null;
  semesterStart?: string | null;
  semesterEnd?: string | null;
  courseAnnex?: string | null;
  gradeSubjects?: string | null;
  userId?: number;
  semesterId?: number | null;
  signedAt?: Date | null;
};

function cnFromYmd(ymd?: string | null) {
  const m = String(ymd || '').match(/^(\d{4})-(\d{1,2})-(\d{1,2})/);
  if (!m) return '';
  return `${m[1]}年${Number(m[2])}月${Number(m[3])}日`;
}

/** 将甲方对公信息 + 乙方认证信息填入合同模板占位符 */
export function buildFilledContract(content: string, input: ContractFillInput) {
  const a = input.partyA || DEFAULT_PARTY_A;
  const when = input.signedAt || new Date();
  const vars: Record<string, string> = {
    合同编号: buildContractNo(input.userId || 0, input.semesterId),
    甲方名称: a.name,
    甲方信用代码: a.creditCode,
    甲方住所: a.address,
    甲方法定代表人: a.legalRep,
    甲方电话: a.phone,
    甲方邮箱: a.email,
    乙方姓名: input.realName || '',
    乙方身份证号: input.idNumber || '',
    乙方住所: input.address || '',
    乙方电话: input.phone || '',
    乙方邮箱: input.email || '',
    乙方开户行: input.bankName || '',
    乙方账户名: input.bankAccountName || input.realName || '',
    乙方账号: input.bankAccount || '',
    签订日期: formatCnDate(when),
    合同开始日: cnFromYmd(input.semesterStart) || formatCnDate(when),
    合同结束日: cnFromYmd(input.semesterEnd) || '',
    学期名称: input.semesterName || '',
    授课年级科目: input.gradeSubjects || '甲方安排年级科目',
    课程附件: input.courseAnnex?.trim()
      || '（暂无预分配课程。具体授课安排以甲方后续《授课计划表》及平台排课为准；报酬标准以平台配置的课时费为准。）',
  };
  return fillContractTemplate(content, vars);
}

export const DEFAULT_CONTRACT = {
  title: '兼职教师劳务合作合同',
  content: "# 兼职教师劳务合作合同（电子签署）\n\n**合同编号：** {{合同编号}}\n**甲方（机构）：** {{甲方名称}}\n**乙方（兼职教师）：** {{乙方姓名}}\n**签订地点：** 线上电子签署\n**签订日期：** {{签订日期}}\n\n\n## 甲方信息\n\n- **名称：** {{甲方名称}}\n- **统一社会信用代码：** {{甲方信用代码}}\n- **住所地：** {{甲方住所}}\n- **法定代表人/授权代表：** {{甲方法定代表人}}\n- **联系电话：** {{甲方电话}}\n- **电子邮箱：** {{甲方邮箱}}\n\n\n## 乙方信息\n\n- **姓名：** {{乙方姓名}}\n- **身份证号码：** {{乙方身份证号}}\n- **住所地：** {{乙方住所}}\n- **联系电话：** {{乙方电话}}\n- **电子邮箱：** {{乙方邮箱}}\n- **收款账户开户行：** {{乙方开户行}}\n- **账户名称：** {{乙方账户名}}\n- **银行账号：** {{乙方账号}}\n\n\n## 鉴于条款\n\n甲方因经营需要开展多学科课外教育培训服务，需聘请兼职教师提供教学劳务；乙方具备对应学科教学能力，自愿以兼职身份向甲方提供本合同约定的劳务。\n\n**双方确认：**\n1. 本合同为劳务合作合同，不属于劳动合同，不建立劳动关系，不受《劳动合同法》等劳动法律法规调整；\n2. 双方依据《中华人民共和国民法典》《中华人民共和国电子签名法》及相关规定，经平等协商，达成如下条款，共同遵照执行；\n3. 本合同以电子形式签署，双方同意使用可靠电子签名，电子签名与手写签名或盖章具有同等法律效力。\n\n\n## 第一条 合作内容与劳务标的\n\n1. 乙方同意按照甲方要求，担任甲方 **{{授课年级科目}}** 兼职培训教师，具体授课安排以甲方每期出具的《授课计划表》为准，详见附件1（系统预分配课程清单）。\n\n2. 乙方提供的劳务范围包括：\n   - 课堂授课；\n   - 备课；\n   - 作业批改；\n   - 学员学习情况反馈；\n   - 配合甲方完成阶段性教学测评；\n   - 甲方要求的其他与本次授课相关的辅助工作。\n\n3. **特别约定：** 乙方确认其不具备与甲方建立劳动关系的意愿，双方之间不构成事实劳动关系。乙方不得以任何理由主张劳动关系项下的权利（包括但不限于社会保险、经济补偿金、加班费等）。\n\n\n## 第二条 合作期限\n\n1. 本合同有效期自 **{{合同开始日}}** 起至 **{{合同结束日}}** 止（对应学期：{{学期名称}}）。\n\n2. 合同到期后，双方未提出书面终止的，可经双方确认后续签；本平台按学期要求重新签订并审核。\n\n3. **提前终止权：** 任何一方提前 **30** 日向对方发出书面通知（含电子邮件、平台站内信等电子形式），可无条件终止本合同，无需承担违约责任。\n\n4. 合同终止后，乙方应当立即归还甲方所有教学资料、学员信息等保密材料，并删除其个人设备中存储的甲方保密信息。\n\n\n## 第三条 AI使用规则\n\n1. **允许范围：** 乙方仅可使用AI工具作为备课辅助，用于整理知识点框架、搜集参考素材。\n\n2. **禁止行为：**\n   - 不得直接将AI生成的内容直接用于授课、课件制作和作业布置；\n   - 不得全盘委托AI生成教学内容、替代本人完成授课准备或教学工作；\n   - 不得将甲方学员的任何个人信息、学习数据、测评结果输入任何AI工具；\n   - 不得将甲方教学内容、内部资料上传至公开AI平台训练模型。\n\n3. **人工审核义务：** 乙方必须对AI生成的所有内容进行人工审核，确保内容的准确性、合规性和符合甲方教学要求，不得直接使用未审核的AI生成内容开展教学活动。\n\n4. **违规责任：** 乙方违反本条约定的，甲方有权立即终止本合同，乙方应赔偿甲方因此遭受的全部损失（包括但不限于学员退费损失、声誉损失等）。\n\n\n## 第四条 上课行为规范\n\n1. **考勤要求：**\n   - 乙方应当至少提前 **30** 分钟到达授课场地，完成课前准备；\n   - 不得迟到、早退；\n   - 每迟到一次，扣除当次授课报酬的 **50%**；\n   - 累计迟到 **2** 次及以上，甲方有权终止本合同。\n\n2. **教学内容：** 乙方应当按照甲方审定的教学大纲和授课计划完成教学内容，不得擅自更改教学内容、降低教学标准，不得提前下课。\n\n3. **课堂纪律：**\n   - 乙方上课期间应当关闭与教学无关的电子设备；\n   - 不得擅自接打电话、刷短视频；\n   - 不得从事与授课无关的活动。\n\n4. **职业操守：**\n   - 乙方应当遵守甲方的教学管理规定；\n   - 不得向学员及家长推销与甲方无关的产品、服务；\n   - 不得引导学员脱离甲方建立私下授课关系；\n   - 不得在课堂内发表违法、违规、违反公序良俗的言论。\n\n5. **课后义务：**\n   - 乙方应当在每节课结束后 **2** 日内完成本次课程学员作业批改；\n   - **2** 日内向甲方反馈学员课堂学习情况；\n   - 配合甲方完成阶段性测评的评改工作。\n\n6. **调课与请假：**\n   - 乙方因个人原因需要调课、请假的，应当至少提前 **3** 日向甲方提出申请；\n   - 经甲方同意后方可调整，不得擅自停课、缺课；\n   - **擅自停课一次，应当向甲方支付当次授课报酬 3 倍的违约金。**\n\n\n## 第五条 劳务报酬与结算\n\n1. **报酬标准：** 本合同项下劳务报酬计算标准见附件1，课时量按照实际完成授课的数量统计。\n\n2. **含税与发票：** 本报酬为含税报酬，乙方应配合甲方开具符合要求的发票。如乙方无法提供发票，甲方有权代扣相应税费后支付。\n\n3. **结算周期：** 报酬结算周期为自然月。甲方应当在每月月底前核对乙方上月实际完成课时量，核对无误后在下月25日（遇节假日顺延至下个工作日），将报酬支付至乙方指定银行账户。\n\n4. **个人所得税：** 乙方同意甲方扣除按照法律法规规定应当由乙方承担的个人所得税，甲方依法履行代扣代缴义务。\n\n5. **甲方逾期支付：**\n   - 每逾期一日，应当按照应付未付金额的 **5‰** 向乙方支付违约金；\n   - 逾期超过 **5** 日的，乙方有权终止本合同，并要求甲方一次性支付全部剩余报酬及违约金。\n\n\n## 第六条 知识产权归属\n\n1. **甲方所有：** 乙方在提供劳务过程中，利用甲方资源、按照甲方要求创作完成的课件、教案、测评资料等教学成果，知识产权归甲方所有。\n\n2. **乙方保留：** 乙方保留对其个人教学方法的自有知识产权，但不得在本合同终止后，使用甲方享有知识产权的教学成果开展教学活动。\n\n3. **侵权赔偿：** 乙方保证其提供的教学内容不侵犯任何第三方的知识产权。若因乙方侵权导致甲方遭受损失，乙方应当全额赔偿甲方损失（包括但不限于赔偿金、律师费、诉讼费、公证费等）。\n\n\n## 第七条 保密义务\n\n1. **保密范围：** 乙方应当对本合同履行过程中知悉的甲方商业秘密、学员个人信息、教学资料、收费标准、内部管理制度等未公开信息承担保密义务，保密清单详见附件2。\n\n2. **保密要求：**\n   - 未经甲方书面同意，乙方不得向任何第三方泄露前述保密信息；\n   - 不得自行使用保密信息用于其他用途；\n   - 不得将保密信息上传至任何AI平台或公开网络。\n\n3. **保密期限：** 本合同终止后，保密义务仍然有效，保密期限为 **2** 年。\n\n4. **违规责任：** 乙方违反保密义务的，应当向甲方支付违约金 **人民币50,000元**，并赔偿甲方因此遭受的全部损失。\n\n\n## 第八条 竞业限制\n\n1. **竞业限制期限：** 本合同履行期间及本合同终止后 **12** 个月内。\n\n2. **竞业限制范围：** 乙方不得在甲方住所地 **10** 公里范围内，自营或为第三方经营与甲方存在竞争关系的同类教培业务。\n\n3. **竞业限制补偿：** 甲方在竞业限制期限内，按照乙方离职前 **12** 个月平均月报酬的 **30%** 按月支付竞业限制补偿金。如甲方未按时支付，乙方有权解除竞业限制义务。\n\n4. **违规责任：** 乙方违反竞业限制约定的，应当向甲方支付违约金 **人民币50,000元**，并赔偿甲方因此遭受的全部损失。\n\n\n## 第九条 双方权利义务\n\n### 甲方权利义务：\n\n1. 按照本合同约定及时向乙方支付劳务报酬；\n2. 提供必要的教学场地、教学设备；\n3. 提前向乙方告知教学要求和学员情况；\n4. 有权对乙方教学质量进行监督、检查和测评；\n5. 有权根据经营需要调整授课安排，但应提前通知乙方。\n\n### 乙方权利义务：\n\n1. 应当具备对应科目教学所需的资质；\n2. 保证教学质量符合甲方公布的验收标准，详见附件3；\n3. 自行承担其在提供劳务过程中发生的人身损害，因甲方原因导致的除外；\n4. 乙方造成第三方人身或财产损害的，由乙方自行承担责任；\n5. 乙方确认其身体健康，能够胜任本合同约定的教学劳务。\n\n\n## 第十条 验收标准\n\n1. **测评周期：** 甲方每 **4** 个月对乙方教学质量进行一次测评。\n\n2. **测评方式：**\n   - 学员满意度调查；\n   - 教学内容完成度检查；\n   - 考试通过率核查。\n\n3. **不合格处理：**\n   - 若乙方测评不合格，乙方应当在 **3** 日内完成整改；\n   - 整改后再次测评仍不合格的，甲方有权终止本合同，按照实际完成课时结算报酬。\n\n\n## 第十一条 违约责任\n\n1. **一般违约：** 乙方违反本合同第四条上课行为规范、第五条报酬约定之外的其他义务的，甲方有权扣除当月费用；造成损失的，乙方另行赔偿。\n\n2. **引导私下授课：** 乙方违反本合同第四条第4款约定，引导学员私下授课的，应当向甲方支付违约金 **人民币10,000元**（大写：壹万元），并赔偿甲方因此遭受的全部学费损失。\n\n3. **甲方违约：** 甲方违反本合同约定，无正当理由拒绝支付报酬的，应当按照应付未付金额的 **5‰** 每日向乙方支付违约金。\n\n4. **赔偿范围：** 违约方应当赔偿守约方因此遭受的全部损失，包括但不限于直接损失、间接损失、律师费、诉讼费、公证费、差旅费等。\n\n\n## 第十二条 不可抗力\n\n1. 因不可抗力不能履行本合同的，根据不可抗力的影响，部分或者全部免除责任。\n\n2. 一方应当在不可抗力发生后 **3** 日内通知对方，并提供有效证明。\n\n3. 不可抗力持续超过 **30** 日的，任何一方有权终止本合同，双方按照实际履行情况结算报酬。\n\n\n## 第十三条 争议解决\n\n1. **协商：** 本合同履行过程中发生的争议，双方应当先协商解决，协商期限为 **30** 日。\n\n2. **诉讼：** 协商不成的，任何一方均有权向 **甲方住所地** 有管辖权的人民法院提起诉讼。\n\n3. **电子证据：** 双方确认，本合同电子签署过程中的电子数据（包括但不限于电子签名、时间戳、签署日志等）可以作为认定案件事实的依据。\n\n\n## 第十四条 电子签署与送达\n\n1. **签署方式：** 本合同通过本平台以手写电子签名方式签署。双方同意电子签名与手写签名或盖章具有同等法律效力。\n\n2. **合同生效：** 本合同自乙方完成电子签名并经甲方（平台管理员）审核通过之日起生效。\n\n3. **合同存储：** 电子合同文件由平台保存，乙方可在「我的合同」中查看、导出。\n\n4. **送达：** 甲方可通过平台消息、短信或预留电话/邮箱向乙方送达通知。\n\n\n## 第十五条 附件与其他\n\n1. 本合同所有附件为本合同不可分割的组成部分，与本合同具有同等法律效力。\n\n2. **本合同附件清单：**\n   - **附件1：** 授课计划表 / 预分配课程清单（系统自动生成）\n   - **附件2：** 保密信息清单\n   - **附件3：** 教学质量验收标准\n\n3. 本合同未尽事宜，双方可另行签订补充协议，补充协议与本合同具有同等法律效力。\n\n\n## 电子签署页\n\n**甲方（盖章）：** {{甲方名称}}\n\n**法定代表人/授权代表：** {{甲方法定代表人}}\n\n**签署日期：** {{签订日期}}\n\n\n**乙方（签字）：** {{乙方姓名}}\n\n**身份证号码：** {{乙方身份证号}}\n\n**电子签名：** （以手写签名图像为准）\n\n**签署日期：** {{签订日期}}\n\n\n## 附件1：授课计划表 / 预分配课程\n\n{{课程附件}}\n\n*说明：未预分配课程时，具体授课安排以甲方后续《授课计划表》及平台排课为准；报酬标准以平台配置的课时费为准。*\n\n\n## 附件2：保密信息清单\n\n1. 甲方学员名单及个人信息（姓名、年龄、学校、联系方式、家庭住址等）；\n2. 甲方学员学习数据、测评结果、成绩记录；\n3. 甲方教学大纲、课件、教案、测评资料；\n4. 甲方收费标准、优惠政策、财务数据；\n5. 甲方内部管理制度、运营流程；\n6. 甲方客户资源、合作渠道；\n7. 其他甲方书面标注为保密的信息。\n\n\n## 附件3：教学质量验收标准\n\n- **学员满意度（权重 40%）：** 满意度评分 ≥ 4.0/5.0\n- **教学内容完成度（权重 30%）：** 按计划完成全部教学内容\n- **考试通过率（权重 30%）：** 学员考试通过率 ≥ 80%\n- **综合评定：** 综合得分 ≥ 75 分为合格\n",
};
